def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Uniform rows establish the background stripe color.
    uniform = [row[0] for row in grid if all(x == row[0] for x in row)]
    bg = max(set(uniform), key=uniform.count)

    for r, row in enumerate(grid):
        if all(x == row[0] for x in row):
            continue

        # Find the trailing run. Recolor a background-colored tail when
        # it follows a substantial non-background pattern/run.
        c = row[-1]
        start = w - 1
        while start > 0 and row[start - 1] == c:
            start -= 1

        if c == bg and start < w:
            non_bg = sum(x != bg for x in row[:start])
            if non_bg >= 4:
                out[r][start:] = [1] * (w - start)
        elif c != bg:
            # In some examples the marked tail is the non-background color,
            # following an initial stripe-colored run.
            k = 0
            while k < w and row[k] == bg:
                k += 1
            if k > 0 and all(x == c for x in row[k:]):
                out[r][k:] = [1] * (w - k)

    return out
